### 2. Políticas de Seguridad RLS Jerárquicas (Multi-Tenant con JWT `app_metadata`)

Se asume que el JWT contiene `tenant_id` y `user_id` (empleado_id) y `role`.

```sql
-- Habilitar RLS en las tablas
ALTER TABLE public.productos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pedidos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.detalles_pedido ENABLE ROW LEVEL SECURITY;

-- Función auxiliar para obtener el tenant_id del JWT
CREATE OR REPLACE FUNCTION public.get_current_tenant_id()
RETURNS UUID
LANGUAGE plpgsql IMMUTABLE
AS $$
BEGIN
  RETURN (current_setting('request.jwt.claims', TRUE)::jsonb->>'tenant_id')::uuid;
END;
$$;

-- Función auxiliar para obtener el user_id (empleado_id) del JWT
CREATE OR REPLACE FUNCTION public.get_current_user_id()
RETURNS UUID
LANGUAGE plpgsql IMMUTABLE
AS $$
BEGIN
  RETURN (current_setting('request.jwt.claims', TRUE)::jsonb->>'user_id')::uuid;
END;
$$;

-- Función auxiliar para obtener el rol del JWT
CREATE OR REPLACE FUNCTION public.get_current_user_role()
RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE
AS $$
BEGIN
  RETURN (current_setting('request.jwt.claims', TRUE)::jsonb->>'role')::text;
END;
$$;

-- Política GLOBAL para SELECT en todas las tablas: Solo usuarios del tenant pueden leer sus datos
-- (Se asume que esta es una política base, y se pueden añadir más específicas)
-- En general, para SELECT, el tenant_id es la primera y principal capa de seguridad.

-- Políticas para `productos`
CREATE POLICY select_productos_by_tenant ON public.productos FOR SELECT TO authenticated
USING (tenant_id = public.get_current_tenant_id() AND activo = TRUE);

-- Para INSERT/UPDATE/DELETE en productos, solo roles con permisos de gestión (e.g., 'admin')
CREATE POLICY manage_productos_by_tenant_admin ON public.productos FOR ALL TO authenticated
USING (tenant_id = public.get_current_tenant_id() AND public.get_current_user_role() = 'admin')
WITH CHECK (tenant_id = public.get_current_tenant_id() AND public.get_current_user_role() = 'admin');

-- Políticas para `pedidos`
-- SELECT: Empleados ven sus propios pedidos, administradores ven todos los del tenant.
CREATE POLICY select_pedidos_by_tenant_and_role ON public.pedidos FOR SELECT TO authenticated
USING (
    tenant_id = public.get_current_tenant_id()
    AND (
        empleado_id = public.get_current_user_id()
        OR public.get_current_user_role() = 'admin'
    )
);

-- INSERT: Empleados con rol 'cajero' o 'empleado' pueden crear pedidos para su tenant, asignándose a sí mismos.
CREATE POLICY insert_pedidos_by_cajero ON public.pedidos FOR INSERT TO authenticated
WITH CHECK (
    tenant_id = public.get_current_tenant_id()
    AND public.get_current_user_role() IN ('cajero', 'empleado')
    AND empleado_id = public.get_current_user_id()
);

-- UPDATE: Empleados pueden actualizar sus pedidos PENDIENTES. Administradores pueden actualizar cualquier pedido del tenant.
CREATE POLICY update_pedidos_by_owner_or_admin ON public.pedidos FOR UPDATE TO authenticated
USING (
    tenant_id = public.get_current_tenant_id()
    AND (
        (empleado_id = public.get_current_user_id() AND estado = 'PENDIENTE')
        OR public.get_current_user_role() = 'admin'
    )
)
WITH CHECK (
    tenant_id = public.get_current_tenant_id()
    AND (
        (empleado_id = public.get_current_user_id() AND estado = 'PENDIENTE')
        OR public.get_current_user_role() = 'admin'
    )
);

-- DELETE: Solo administradores pueden eliminar pedidos (generalmente se prefiere cambiar el estado a 'ANULADO').
CREATE POLICY delete_pedidos_by_admin ON public.pedidos FOR DELETE TO authenticated
USING (tenant_id = public.get_current_tenant_id() AND public.get_current_user_role() = 'admin');

-- Políticas para `detalles_pedido`
-- SELECT: Asociado a los permisos de `pedidos`. Un usuario solo ve detalles de pedidos que puede ver.
CREATE POLICY select_detalles_pedido_via_pedidos ON public.detalles_pedido FOR SELECT TO authenticated
USING (
    tenant_id = public.get_current_tenant_id()
    AND EXISTS (
        SELECT 1 FROM public.pedidos p
        WHERE p.id = detalles_pedido.pedido_id
          AND p.tenant_id = detalles_pedido.tenant_id
          AND (p.empleado_id = public.get_current_user_id() OR public.get_current_user_role() = 'admin')
    )
);

-- INSERT/UPDATE/DELETE en `detalles_pedido` se gestionarán EXCLUSIVAMENTE mediante funciones RPC
-- para asegurar la integridad transaccional junto con `pedidos` y `productos`.
-- No se otorgan permisos directos a roles para estas operaciones en `detalles_pedido`.
